import os,re,collections
root='.'
files=[]
for d,ds,fs in os.walk('internal'):
  for f in fs:
    if f.endswith('.go'):
      files.append(os.path.join(d,f))
decls=[]
for p in files:
 s=open(p).read()
 pkg=re.search(r'^package\s+(\w+)',s,re.M).group(1)
 for m in re.finditer(r'^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(',s,re.M):
  decls.append((m.group(1),pkg,p))
alltext='\n'.join(open(os.path.join(d,f)).read() for d,ds,fs in os.walk('.') if '.git' not in d.split(os.sep) for f in fs if f.endswith('.go'))
for name,pkg,p in decls:
 n=len(re.findall(r'(?<!func\s)(?<!\w)'+re.escape(name)+r'\s*\(',alltext))-1
 # selected calls package.Name plus maybe any same package use; crude
 print(f'{n:4} {pkg}.{name} {p}')
PY

