for $p (@i) { open F,"<",$p; local $/; $s=<F>; close F; ($pkg)=$s =~ /^package\s+(\w+)/m; while($s =~ /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/mg) { $n=$1; $c=()=$all =~ /(?<!func\s)(?<!\w)\Q$n\E\s*\(/g; push @r, [$c-1,"$pkg.$n",$p] } }
for (sort {$b->[0]<=>$a->[0]} @r) { print "$$_[0] $$_[1] $$_[2]\n" }
'

